pub fn sum_parallel(values: &[i32]) -> i32 {
    thread::scope(|scope| {
        let handles: Vec<_> = values
            .chunks(2)
            .map(|chunk| scope.spawn(move || chunk.iter().sum::<i32>()))
            .collect();
        handles.into_iter().map(|handle| handle.join().unwrap()).sum()
    })
}

